    function VehicleLink({r}:{r:Transport}){const canReadTrips=['allocator','approver','driver'].includes(role)&&load==='ready',legs=canReadTrips?linkedVehicleLegs(r):[];return <div className="related-return"><Route/><div><strong>Vehicle trip history</strong><p>{!canReadTrips?'Vehicle-trip access is checked separately.':legs.length?legs.length+' linked vehicle movements · '+legs.map(v=>v.id).join(', '):'No matched vehicle movement yet. The passenger journey remains its own record.'}</p></div><Button variant="outline" onClick={()=>openSource('Vehicle trip history',r)}>Open vehicle trip history</Button></div>}
